// One-time script: generate the static SAML metadata XML fixtures used
// by the parser test suite. Reads the PEMs from
// tests/fixtures/saml/certs/ (which were generated by
// scripts/generate-saml-test-certs.sh) and writes one XML file per
// scenario into tests/fixtures/saml/.
//
// Run via:  npx tsx scripts/generate-saml-test-fixtures.ts
//
// Like the cert script, the OUTPUT is what the tests load — re-run
// only when expanding the fixture set. Idempotent.

import * as fs from 'node:fs'
import * as path from 'node:path'

const CERT_DIR = path.resolve('tests/fixtures/saml/certs')
const OUT_DIR = path.resolve('tests/fixtures/saml')

function pemToBase64(pemFilename: string): string {
  const pem = fs.readFileSync(path.join(CERT_DIR, pemFilename), 'utf8')
  return pem
    .replace(/-----BEGIN CERTIFICATE-----/g, '')
    .replace(/-----END CERTIFICATE-----/g, '')
    .replace(/\s+/g, '')
}

const VALID_CERT = pemToBase64('valid-sha256-rsa-2048.pem')
const SECOND_CERT = pemToBase64('valid-sha384-rsa-3072.pem')
const SHA1_CERT = pemToBase64('sha1-rsa-2048.pem')
const EXPIRED_CERT = pemToBase64('expired-rsa-2048.pem')
const NOT_YET_VALID_CERT = pemToBase64('not-yet-valid-rsa-2048.pem')
const WEAK_RSA_CERT = pemToBase64('weak-rsa-1024.pem')

function write(name: string, content: string): void {
  fs.writeFileSync(path.join(OUT_DIR, name), content, 'utf8')
  console.log(`wrote ${name} (${content.length} bytes)`)
}

