write(
  'oversized.xml',
  // Slightly over 1 MB. We use ASCII padding inside an XML comment...
  // but our parser rejects on byte length BEFORE checking for comments,
  // so the contents of the padding is irrelevant.
  `<?xml version="1.0" encoding="UTF-8"?>
<md:EntityDescriptor xmlns:md="urn:oasis:names:tc:SAML:2.0:metadata" entityID="https://example.com/idp/big">
  <md:IDPSSODescriptor protocolSupportEnumeration="urn:oasis:names:tc:SAML:2.0:protocol">
    ${'<!-- pad pad pad pad pad pad pad pad pad pad pad pad pad pad pad pad pad pad pad pad -->'.repeat(13000)}
  </md:IDPSSODescriptor>
</md:EntityDescriptor>
`,
)

write(
  'deeply-nested.xml',
  // 25 levels of nesting (20 + a few extra). The parser tree mirrors
  // the XML tree, so depth walk should reject.
  `<?xml version="1.0" encoding="UTF-8"?>
${'<wrap>'.repeat(25)}
<md:EntityDescriptor xmlns:md="urn:oasis:names:tc:SAML:2.0:metadata" entityID="https://example.com/idp/deep">
  <md:IDPSSODescriptor protocolSupportEnumeration="urn:oasis:names:tc:SAML:2.0:protocol"/>
</md:EntityDescriptor>
${'</wrap>'.repeat(25)}
`,
)

